.the-list li{ margin-bottom: 8px; list-style: disc; margin-inline-start: 16px; } table{position:relative;overflow:hidden;width:100%;max-width:100%;color:#fff;text-align:center;background-color:#000000;border:2px solid #ffeb00;border-collapse:separate;border-radius:12px}         table.table-layout-fixed{table-layout:fixed}table.table-has-caption{border-top:none;border-top-left-radius:0;border-top-right-radius:0}table caption{padding:15px;color:#fff;font-size:14px;font-weight:700;line-height:24px;text-transform:uppercase;background-color:#000;border-top-left-radius:12px;border-top-right-radius:12px}table tr td,table tr th{padding:10px;line-height:24px;vertical-align:middle;border:1px solid #ffeb00}table thead tr th{color:rgb(255, 255, 255);background-color:linear-gradient(135deg, #e4b900, #ffeb00, #efe800);border-bottom:2px solid #ffeb00}table tr:last-of-type:not(:first-of-type) td,table tr:last-of-type:not(:first-of-type) th{border-bottom:none}table tfoot tr td,table tfoot tr th{border:none}table tfoot tr:first-of-type td,table tfoot tr:first-of-type th{border-top:2px solid #ffeb00}table tr td .button,table tr td button,table tr th .highlight{color:#000;font-size:20px;font-weight:700}table tr .responsive-th{display:none;overflow:hidden;position:absolute;left:4%;width:44%;color:#000;font-size:16px;text-overflow:ellipsis;text-align:right;white-space:nowrap} .button.button-secondary,button.button-secondary{color:#fff;background-color:linear-gradient(135deg, #e4b900, #ffeb00, #efe800)}.button.button-primary,.button.button-secondary,button.button-primary,button.button-secondary{padding:7px 22px;border-radius:6px}.marquee{width:100%;margin:0 auto;white-space:nowrap;overflow:hidden;box-sizing:border-box;height:24px;font-family:prompt,arial;text-transform:uppercase;font-size:14px;color:#ffff;font-style:bold;margin-bottom:0px}.marquee span{display:inline-block;padding-left:100%;text-indent:0;animation:marquee 30s linear infinite}.marquee span:hover{animation-play-state:paused}@keyframes marquee{0%{transform:translate(0,0)}100%{transform:translate(-100%,0)}}p{text-align:justify}.submenu{color:#5db;margin:0}.nomargin{margin:0}.seo-content{font-size:.12.8em;color:#d3d3d3;text-align:justify;letter-spacing:.1px}.btn{display: grid;padding:6px 12px;margin-bottom:0;font-size: large;font-weight:400;line-height:1.42857143;text-align:center;white-space:nowrap;vertical-align:middle;-ms-touch-action:manipulation;touch-action:manipulation;cursor:pointer;-webkit-user-select:none;-moz-user-select:none;-ms-user-select:none;user-select:none;background-image:none;border:1px solid transparent;border-radius:4px;}.menu a {display: inline-block;padding: 10px 20px;text-decoration: none;color: white;margin: 0px;font-size: 18px;}.menu {display: block;width: 100%;text-align: center;background: #ffeb00;}.menu a:hover {color: #ffeb00;}.menu a {display: block;font-size: 16px;border: 1px solid white;}
html {scroll-behavior:smooth;}
a {
text-decoration: none;
}
@media only screen and (min-width: 320px) and (max-width: 840px) {
body {
  background-color:#242424;
  background-image:url(https://i.ibb.co/yMFSRdc/Banner-FUJI66-3.png);
background-size: cover;
background-attachment: fixed;
margin: 0;
display: block;
}
.logo{text-align:center;margin-left: 10px;margin-top: 1px;width:50%;}
}
@media only screen and (min-width: 840px) and (max-width: 2000px) {
body {
  background-color:#242424;
  background-image:url(https://i.ibb.co/yMFSRdc/Banner-FUJI66-3.png);
background-size: cover;
background-attachment: fixed;
margin: 0;
display: block;
}
.logo{text-align:center;margin-left: 10px;margin-top: 0px;width:18%;}
}
label {
font-family: "Raleway", sans-serif;
font-size: 11pt;
}
#forgot-pass {
color: #46ce10;
font-family: "Raleway", sans-serif;
font-size: 10pt;
margin-top: 3px;
text-align: right;
}
#card {
    margin: -35px;
    margin-top: 10px;
    width: 100%;
    margin-left: 0px;
}
#card-content {
padding: 0px 5px;
}
#card-title {
font-family: "Raleway Thin", sans-serif;
letter-spacing: 4px;
padding-bottom: 23px;
padding-top: 15px;
text-align: center;
color: white;
}
#signup {
color: #46ce10;
font-family: "Raleway", sans-serif;
font-size: 10pt;
margin-top: 16px;
text-align: center;
}
#submit-btn {
background: -webkit-linear-gradient(right, #ffeb00, #46ce10);
border: none;
border-radius: 21px;
box-shadow: 0px 1px 8px #46ce10;
cursor: pointer;
color: white;
font-family: "Raleway SemiBold", sans-serif;
height: 42.3px;
margin: 0 auto;
margin-top: 50px;
transition: 0.25s;
width: 153px;
}
#submit-btn:hover {
box-shadow: 0px 1px 18px #46ce10;
}
.form {
align-items: left;
display: flex;
flex-direction: column;
}
.form-border {
background: -webkit-linear-gradient(right, #ffeb00, #46ce10);
height: 1px;
width: 100%;
}
.form-content {
background: #fbfbfb;
border: none;
outline: none;
padding-top: 14px;
}
.underline-title {
background: -webkit-linear-gradient(right, #fff, #fff);
height: 2px;
margin: -1.1rem auto 0 auto;
width: 100%;
}
.contactField.requiredField, .contactField.contactOption {
    height: 35px;
    margin-bottom: 0px;
